name: Auto‑approve workflows for returning contributors and ok‑to‑test PRs

on:
  pull_request_target:
    types: [labeled, synchronize]
    branches:
      - main
      - 'release-*'

jobs:
  approve:
    if: github.event.pull_request.base.ref == 'main' || startsWith(github.event.pull_request.base.ref, 'release-')
    runs-on: ubuntu-latest
    permissions:
      actions: write
      contents: read
      pull-requests: read
    steps:
      - name: Check if PR has ok‑to‑test label
        id: check_labels
        run: |
          echo "ok_to_test=false" >> $GITHUB_OUTPUT
          for label in $(jq -r '.pull_request.labels[].name' $GITHUB_EVENT_PATH); do
            if [ "$label" == "ok-to-test" ]; then
              echo "ok_to_test=true" >> $GITHUB_OUTPUT
              break
            fi
          done

      - name: Check if contributor is returning
        id: check_contributor
        uses: actions/github-script@v6
        with:
          script: |
            const prCreator = context.payload.pull_request.user.login;
            const repo = context.repo;
            const query = `repo:${repo.owner}/${repo.repo} type:pr author:${prCreator}`;
            const result = await github.request('GET /search/issues', { q: query, per_page: 1 });
            const total = result.data.total_count;
            const isReturning = total > 1;
            core.setOutput('is_returning', isReturning);

      - name: Approve pending workflow runs
        if: steps.check_labels.outputs.ok_to_test == 'true' || steps.check_contributor.outputs.is_returning == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const headBranch = pr.head.ref;
            let page = 1;
            const per_page = 100;
            while (true) {
              const { data } = await github.actions.listWorkflowRunsForRepo({
                owner,
                repo,
                event: 'pull_request',
                head_branch: headBranch,
                status: 'queued',
                per_page,
                page
              });
              for (const run of data.workflow_runs) {
                if (run.status === 'queued' && !run.conclusion) {
                  await github.actions.approveWorkflowRun({
                    owner,
                    repo,
                    run_id: run.id
                  });
                  console.log(`Approved workflow run ${run.id}`);
                }
              }
              if (data.workflow_runs.length < per_page) break;
              page++;
            }
